# power_set :: [1,2,3]
def power_set(xs):
    n = len(xs)
    return [tuple(xs[i] for i in range(n) if (mask >> i) & 1)
            for mask in range(1 << n)]

if __name__ == '__main__':
    print(power_set([1,2,3]))

